<template>
 <main class="bargain-records"><header class="heading"><div><h2>砍价运营记录</h2><p class="hint">全部历史参与记录，每页15条。过期状态只作显示投影，不修改参与记录。</p></div><template v-for="control in controls" :key="control.key"><button v-if="session.allowed.value" type="button" @click="control.refresh">刷新记录</button></template></header>
 <el-alert v-if="!session.allowed.value" title="当前账号没有砍价运营记录查看权限" type="warning" :closable="false" />
 <template v-else><div class="filters" v-for="control in controls" :key="control.key"><label>搜索<input aria-label="砍价记录搜索" :value="draftKeyword" placeholder="用户昵称、UID或活动名称" @input="control.keyword(($event.target as HTMLInputElement).value)" @keyup.enter="control.search" /></label><label>砍价状态<select aria-label="砍价记录状态" :value="draftStatus" @change="control.status(($event.target as HTMLSelectElement).value)"><option value="">全部状态</option><option value="1">进行中</option><option value="2">已失败 / 已到期</option><option value="3">可购买</option><option value="4">已创建订单</option></select></label><label>活动ID<input aria-label="砍价记录活动ID" inputmode="numeric" :value="draftActivity" @input="control.activity(($event.target as HTMLInputElement).value)" @keyup.enter="control.search" /></label><label>开始日期<input type="date" aria-label="砍价记录开始日期" :value="draftStart" @input="control.start(($event.target as HTMLInputElement).value)" /></label><label>结束日期<input type="date" aria-label="砍价记录结束日期" :value="draftEnd" @input="control.end(($event.target as HTMLInputElement).value)" /></label><div class="actions"><button type="button" @click="control.search">查询记录</button><button type="button" @click="control.reset">重置筛选</button></div></div>
 <p v-if="filterError" role="alert" class="bad">{{ filterError }}</p><p v-if="error" role="alert" class="bad">{{ error }} <button v-for="control in controls" :key="control.key" type="button" @click="control.retry">重试记录列表</button></p>
 <BargainRecordTable :rows="records" :loading="loading" :enabled="session.allowed.value" :source-current="recordLease" :statistics="session.has('bargain_statistics.view')" @helpers="showHelpers" @statistics="openStatistics" />
 <nav v-if="!loading && !error" class="pager" aria-label="砍价记录分页"><span>第 {{ page }} 页 · 共 {{ count }} 条</span><template v-for="control in controls" :key="control.key"><button type="button" :disabled="page<=1" @click="control.previous">上一页</button><button type="button" :disabled="page*15>=count || page>=667" @click="control.next">下一页</button></template></nav><p v-if="count>10005" class="hint">最多浏览前10005条，请缩小筛选范围。</p></template>
 <BargainHelpers v-if="helpersVisible" v-model="helpersVisible" :source-current="helperLease" :record-id="helperRecord" />
 </main>
</template>
<script setup lang="ts">
import {computed,ref} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import BargainRecordTable from './BargainRecordTable.vue';
import BargainHelpers from './BargainHelpers.vue';
import {apiBargainRecords,bargainReadDays,bargainReadId,bargainReadError,type BargainRecord,type BargainRecordQuery} from '@/api/bargainRecords';
import {useBargainReadSession} from './bargainReadSession';
const route=useRoute(),router=useRouter(),records=ref<BargainRecord[]>([]),loading=ref(false),error=ref(''),filterError=ref(''),page=ref(1),count=ref(0);
const draftKeyword=ref(''),draftStatus=ref(''),draftActivity=ref(''),draftStart=ref(''),draftEnd=ref(''),intent=ref(0),helpersVisible=ref(false),helperRecord=ref(0),helperLease=ref<()=>boolean>(()=>false);
let applied:Omit<BargainRecordQuery,'page'|'limit'>={keyword:'',status:''};
function resetDraft(){draftKeyword.value=draftStatus.value=draftActivity.value=draftStart.value=draftEnd.value='';applied={keyword:'',status:''};intent.value++;}
function discard(){records.value=[];loading.value=false;error.value=filterError.value='';page.value=1;count.value=0;helpersVisible.value=false;helperRecord.value=0;resetDraft();}
const session=useBargainReadSession(()=> 'bargain_record.view',()=>route.fullPath,discard,()=>void load(1));
async function load(target=page.value){if(!Number.isSafeInteger(target)||target<1||target>667)return;const job=session.begin('records');if(!job)return;intent.value++;records.value=[];count.value=0;page.value=target;loading.value=true;error.value='';helpersVisible.value=false;try{const result=await apiBargainRecords({...applied,page:target,limit:15},job.signal);if(job.current()){records.value=result.list;count.value=result.count;}}catch(reason){if(job.current())error.value=bargainReadError(reason,'砍价参与记录读取失败');}finally{if(job.current())loading.value=false;job.finish();}}
function search(){if(!session.allowed.value)return;try{const activity=draftActivity.value.trim(),status=draftStatus.value;if(activity&&!bargainReadId(activity))throw Error('请输入有效砍价活动ID');if(!['','1','2','3','4'].includes(status))throw Error('砍价状态无效');const keyword=draftKeyword.value.trim();if([...keyword].length>100)throw Error('搜索内容不能超过100个字符');applied={keyword,status:status?Number(status) as 1|2|3|4:'',...bargainReadDays(draftStart.value,draftEnd.value),...(activity?{bargain_id:Number(activity)}:{})};filterError.value='';void load(1);}catch(reason){filterError.value=bargainReadError(reason,'筛选无效');}}
function showHelpers(row:BargainRecord){if(!session.allowed.value||loading.value||!records.value.includes(row))return;const view=session.lease(),version=intent.value,source=JSON.stringify(row);helperRecord.value=row.id;helpersVisible.value=true;helperLease.value=()=>view.current()&&version===intent.value&&helpersVisible.value&&helperRecord.value===row.id&&records.value.includes(row)&&JSON.stringify(row)===source&&!loading.value;}
function openStatistics(row:BargainRecord){if(session.allowed.value&&session.has('bargain_statistics.view')&&!loading.value&&records.value.includes(row)&&row.bargain_id>0)void router.push('/activity/bargain-statistics/'+row.bargain_id);}
const recordLease=computed(()=>{const view=session.lease(),version=intent.value;return()=>view.current()&&version===intent.value&&!loading.value;});
const controls=computed(()=>{const view=session.lease(),version=intent.value,current=()=>view.current()&&version===intent.value;const input=(change:()=>void)=>{if(view.current()){change();helpersVisible.value=false;intent.value++;}};return [{key:view.key,keyword:(v:string)=>input(()=>draftKeyword.value=v),status:(v:string)=>input(()=>draftStatus.value=v),activity:(v:string)=>input(()=>draftActivity.value=v),start:(v:string)=>input(()=>draftStart.value=v),end:(v:string)=>input(()=>draftEnd.value=v),search:()=>{if(current())search();},reset:()=>{if(current()){resetDraft();filterError.value='';void load(1);}},refresh:()=>{if(current())void load(1);},retry:()=>{if(current())void load(page.value);},previous:()=>{if(current()&&!loading.value&&page.value>1)void load(page.value-1);},next:()=>{if(current()&&!loading.value&&page.value*15<count.value)void load(page.value+1);}}];});
</script>
<style scoped>
.bargain-records{min-width:0}.heading,.actions,.pager{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.heading h2{margin:0;font-size:20px}.hint{font-size:12px;line-height:1.6;color:#747b87}.filters{display:flex;gap:12px;align-items:end;flex-wrap:wrap;margin:18px 0}.filters label{display:grid;gap:6px;font-size:13px;flex:1 1 160px;min-width:0}.filters input,.filters select{width:100%;box-sizing:border-box;min-width:0;padding:8px;border:1px solid #dcdfe6;border-radius:4px;background:#fff;font:inherit}button{font:inherit;padding:7px 11px;border:1px solid #dcdfe6;border-radius:4px;background:#fff;color:#356ac3;cursor:pointer}button:disabled{opacity:.5;cursor:default}.pager{justify-content:flex-end;margin-top:18px;font-size:13px}.bad{color:#c45656;overflow-wrap:anywhere}@media(max-width:650px){.filters{display:grid;grid-template-columns:minmax(0,1fr)}.pager{justify-content:center}}
</style>
